const $=id=>document.getElementById(id),uid=()=>crypto.randomUUID(),clone=x=>structuredClone(x),STORE='map-workspace-project-v2';
const defaultLayer={id:uid(),name:'標繪圖層 1',visible:true,objects:[]};
let state={version:2,layers:[defaultLayer],activeLayerId:defaultLayer.id,settings:{unit:'nm',format:'dms',color:'#f3ba68',basemap:'vector',routes:true,fixes:true,grid:true,selectedRoutes:null,referenceVisibility:{}},instruments:{ruler:{visible:false,x:.53,y:.43,rotation:0,range:null},protractor:{visible:false,x:.55,y:.5,rotation:0}}};
let initialWarning='';
try{const stored=localStorage.getItem(STORE);if(stored){state=validateProject(JSON.parse(stored));state.settings={...{unit:'nm',format:'dms',color:'#f3ba68',basemap:'vector',routes:true,fixes:true,grid:true,selectedRoutes:null,referenceVisibility:{}},...state.settings};state.instruments={ruler:{visible:false,x:.53,y:.43,rotation:0,range:null,...state.instruments?.ruler},protractor:{visible:false,x:.55,y:.5,rotation:0,...state.instruments?.protractor}}}else{const legacy=JSON.parse(localStorage.getItem('atlas-objects')||'[]');if(Array.isArray(legacy)&&legacy.length){defaultLayer.objects=legacy.map(o=>({...o,description:o.description||''}));validateProject(state)}const unit=localStorage.getItem('atlas-unit'),base=localStorage.getItem('atlas-basemap'),color=localStorage.getItem('map-drawing-color');if(['nm','km','m'].includes(unit))state.settings.unit=unit;if(['vector','street','satellite'].includes(base))state.settings.basemap=base;if(/^#[\da-f]{6}$/i.test(color))state.settings.color=color}}catch{initialWarning='舊資料未自動載入；原始本機資料仍保留，可使用 KML 或專案備份恢復。'}
let history=[],selected=null,tool='pan',draftPoints=[],routes=[],references=[],lastCursor=[24,121],routePaths=new Map(),referencePaths=new Map(),objectPaths=new Map(),toastTimer,installPrompt,freePointer=null,clickTimer;
const map=L.map('map',{zoomControl:false,doubleClickZoom:false,minZoom:2,maxZoom:15}).setView([24,121],6);
L.control.zoom({position:'bottomright'}).addTo(map);map.attributionControl.addAttribution('Natural Earth · <a href="https://github.com/dkaoster/taiwan-atlas" target="_blank" rel="noopener">Taiwan Atlas / 內政部</a> · CAA eAIP');
const land=L.layerGroup(),routeLines=L.layerGroup().addTo(map),fixes=L.layerGroup().addTo(map),referenceGroup=L.layerGroup().addTo(map),grid=L.layerGroup().addTo(map),draw=L.layerGroup().addTo(map),handles=L.layerGroup().addTo(map),draft=L.layerGroup().addTo(map);
