function axisFormat(value,lat,step){const v=lat?value:((value+180)%360+360)%360-180,hemisphere=lat?(v<0?'S':'N'):(v<0?'W':'E');if(state.settings.format==='decimal')return Number(Math.abs(v).toFixed(5))+'°'+hemisphere;if(step>=1)return Math.round(Math.abs(v))+'°'+hemisphere;if(step>=1/60-1e-10){const total=Math.round(Math.abs(v)*60);return Math.floor(total/60)+'°'+String(total%60).padStart(2,'0')+'′'+hemisphere}const total=Math.round(Math.abs(v)*3600);return Math.floor(total/3600)+'°'+String(Math.floor(total%3600/60)).padStart(2,'0')+'′'+String(total%60).padStart(2,'0')+'″'+hemisphere}
function axisStep(range,count){const rough=range/Math.max(1,count);return[1/3600,2/3600,5/3600,10/3600,15/3600,30/3600,1/60,2/60,5/60,10/60,15/60,30/60,1,2,5,10,15,20,30,45,60,90,180].find(s=>s>=rough)||180}
function renderAxes(){const size=map.getSize(),usableHeight=size.y-93;if(size.x<100||usableHeight<30)return;const longitudeAxis=$('longitude-axis'),latitudeAxis=$('latitude-axis');longitudeAxis.replaceChildren();latitudeAxis.replaceChildren();const left=map.containerPointToLatLng([100,usableHeight]),right=map.containerPointToLatLng([size.x-15,usableHeight]),top=map.containerPointToLatLng([0,15]),bottom=map.containerPointToLatLng([0,usableHeight-10]),lngStep=axisStep(right.lng-left.lng,Math.max(1,Math.floor((size.x-100)/155))),latStep=axisStep(top.lat-bottom.lat,Math.max(1,Math.floor(usableHeight/95)));for(let lng=Math.ceil(left.lng/lngStep)*lngStep;lng<=right.lng;lng+=lngStep){const x=map.latLngToContainerPoint([map.getCenter().lat,lng]).x;const label=document.createElement('span');label.className='axis-label longitude-label';label.style.left=x+'px';label.textContent=axisFormat(lng,false,lngStep);longitudeAxis.append(label)}for(let lat=Math.ceil(bottom.lat/latStep)*latStep;lat<=top.lat;lat+=latStep){const y=map.latLngToContainerPoint([lat,map.getCenter().lng]).y;const label=document.createElement('span');label.className='axis-label latitude-label';label.style.top=y+'px';label.textContent=axisFormat(lat,true,latStep);latitudeAxis.append(label)}}
function updateScale(){const y=Math.max(0,map.getSize().y-100),a=map.containerPointToLatLng([15,y]),b=map.containerPointToLatLng([115,y]),range=distance([a.lat,a.lng],[b.lat,b.lng])/factor(state.settings.unit);if(!(range>0))return;const p=10**Math.floor(Math.log10(range)),value=([5,2,1].find(n=>n*p<=range)||1)*p;scaleElement.style.width=100*value/range+'px';scaleElement.textContent=Number(value.toPrecision(6))+' '+state.settings.unit.toUpperCase()}
