function instrumentPosition(name){const el=$(name),s=state.instruments[name],size=map.getSize(),width=Math.max(100,Math.min(instrumentSizes[name].width,size.x-24)),height=name==='ruler'?90:width;el.hidden=!s.visible;el.style.width=width+'px';el.style.height=height+'px';el.style.left=s.x*size.x+'px';el.style.top=s.y*size.y+'px';el.style.transform=`translate(-50%,-50%) rotate(${s.rotation}deg)`;}
function drawRuler(){if(!state.instruments.ruler.visible)return;const g=instrumentGeometry('ruler'),pad=18,length=Math.max(10,g.width-pad*2),startPx=instrumentPoint(g,pad,20),start=map.containerPointToLatLng(startPx),metresAt=px=>{const at=map.containerPointToLatLng(instrumentPoint(g,pad+px,20));return distance([start.lat,start.lng],[at.lat,at.lng])};const range=metresAt(length)/factor(state.settings.unit),interval=niceInterval(range),decimals=Math.max(0,-Math.floor(Math.log10(interval)));const toPx=value=>{let lo=0,hi=length;for(let n=0;n<24;n++){const mid=(lo+hi)/2;if(metresAt(mid)<value*factor(state.settings.unit))lo=mid;else hi=mid}return pad+(lo+hi)/2};let svg=`<rect x="1" y="1" width="${g.width-2}" height="88" rx="4" fill="#11253260" stroke="#f8e7b9"/><line x1="${pad}" y1="20" x2="${g.width-pad}" y2="20" stroke="#fff0c6"/>`;
 const band=state.instruments.ruler.range;if(band){const from=band.fromM/factor(state.settings.unit),to=band.toM/factor(state.settings.unit);if(from<range){const x=toPx(from),end=toPx(Math.min(to,range));svg+=`<rect id="ruler-range-band" x="${x}" y="20" width="${Math.max(0,end-x)}" height="38" fill="${band.color}" fill-opacity=".4"/>`}}
 for(let i=0;i*interval/5<=range&&i<150;i++){const value=i*interval/5,x=toPx(value),major=i%5===0;svg+=`<line x1="${x}" y1="20" x2="${x}" y2="${major?43:31}" stroke="#fff0c6" stroke-width="${major?1.2:.7}"/>`;if(major)svg+=`<text x="${x}" y="57" text-anchor="middle" fill="#fff0c6" font-size="11" font-family="monospace">${value.toFixed(Math.min(6,decimals))}</text>`}
 const label=state.settings.unit.toUpperCase()+' · '+((state.instruments.ruler.rotation%360+360)%360).toFixed(1)+'°';svg+=`<text x="${g.width/2}" y="78" text-anchor="middle" fill="#fff0c6" font-size="11">${label}</text>`;$('ruler-svg').setAttribute('viewBox',`0 0 ${g.width} 90`);$('ruler-svg').innerHTML=svg;$('ruler-svg').setAttribute('aria-label','地圖直尺 '+label);if(band){const from=band.fromM/factor(state.settings.unit),to=band.toM/factor(state.settings.unit);$('range-feedback').textContent=`已標示 ${Number(from.toFixed(6))}–${Number(to.toFixed(6))} ${state.settings.unit.toUpperCase()}${to>range?'；超出目前尺長的部分會在可見範圍內裁切':''}`}}
