 el.addEventListener('pointerdown',e=>{if(!e.target.closest('[data-instrument]')||e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();e.stopPropagation();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});el.setPointerCapture(e.pointerId);gestures.set(name,true);begin()});
