function downloadProject(){save();const backup={...clone(state),savedAt:new Date().toISOString()};download(JSON.stringify(backup,null,2),'map-workspace-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('所有圖層與設定已儲存，並下載專案備份')}
$('save-project').onclick=downloadProject;$('project-download').onclick=downloadProject;$('project-open').onclick=()=>$('project-file').click();
function sanitizePreferences(){const defaults={unit:'nm',format:'dms',color:'#f3ba68',basemap:'vector',routes:true,fixes:true,grid:true,selectedRoutes:null,referenceVisibility:{},selectedWaypointIds:null};state.settings={...defaults,...state.settings};const s=state.settings;if(!['nm','km','m'].includes(s.unit))s.unit='nm';if(!['dms','decimal'].includes(s.format))s.format='dms';if(!['vector','street','satellite'].includes(s.basemap))s.basemap='vector';if(!/^#[\da-f]{6}$/i.test(s.color))s.color='#f3ba68';if(s.selectedRoutes!==null)s.selectedRoutes=Array.isArray(s.selectedRoutes)?s.selectedRoutes.filter(x=>typeof x==='string').slice(0,300):null;if(!s.referenceVisibility||typeof s.referenceVisibility!=='object')s.referenceVisibility={};for(const key of ['routes','fixes','grid'])s[key]=s[key]!==false;s.customColors=Array.isArray(s.customColors)?s.customColors.filter(c=>/^#[\da-f]{6}$/i.test(c)).slice(0,2000):[];if(s.selectedWaypointIds!==null)s.selectedWaypointIds=Array.isArray(s.selectedWaypointIds)?s.selectedWaypointIds.filter(x=>typeof x==='string'):null;state.instruments||={};for(const name of ['ruler','protractor']){const data=state.instruments[name]||{};const normalized={visible:data.visible===true,x:Number.isFinite(data.x)?Math.max(0,Math.min(1,data.x)):.52,y:Number.isFinite(data.y)?Math.max(0,Math.min(.88,data.y)):.45,rotation:Number.isFinite(data.rotation)?data.rotation%360:0};if(name==='ruler'){normalized.range=null;if(data.range&&Number.isFinite(data.range.fromM)&&Number.isFinite(data.range.toM)&&data.range.fromM>=0&&data.range.toM>data.range.fromM&&/^#[\da-f]{6}$/i.test(data.range.color))normalized.range={fromM:data.range.fromM,toM:data.range.toM,color:data.range.color}}state.instruments[name]=normalized}}
$('project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('專案檔超過 20 MB');const imported=validateProject(JSON.parse(await file.text()));download(JSON.stringify(state,null,2),'map-workspace-before-open-'+Date.now()+'.json','application/json');snapshot();state=imported;sanitizePreferences();selected=null;$('editor-panel').hidden=true;setTool('pan');refreshUI();save('已開啟專案，原專案已下載備份')}catch(e){toast('開啟失敗：'+e.message)}e.target.value=''};
function escapeXML(s){return String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}
function exportKML(){const layer=activeLayer();const placemarks=layer.objects.map(o=>{const p=o.points.map(p=>`${p[1]},${p[0]},${p[2]||0}`);if(o.type==='polygon')p.push(p[0]);const coordinates='<coordinates>'+p.join(' ')+'</coordinates>',geometry=o.type==='point'?'<Point>'+coordinates+'</Point>':o.type==='line'?'<LineString>'+coordinates+'</LineString>':'<Polygon><outerBoundaryIs><LinearRing>'+coordinates+'</LinearRing></outerBoundaryIs></Polygon>';const c=o.color.slice(1),color='ff'+c.slice(4,6)+c.slice(2,4)+c.slice(0,2);return`<Placemark><name>${escapeXML(o.name)}</name><description>${escapeXML(o.description||'')}</description><Style><LineStyle><color>${color}</color><width>2</width></LineStyle><PolyStyle><color>30${color.slice(2)}</color></PolyStyle><IconStyle><color>${color}</color></IconStyle></Style>${geometry}</Placemark>`}).join('');download('<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>'+escapeXML(layer.name)+'</name>'+placemarks+'</Document></kml>',layer.name.replace(/[<>:"/\\|?*]/g,'_')+'.kml','application/vnd.google-earth.kml+xml');toast('已匯出目前圖層的 '+layer.objects.length+' 個物件')}
$('export-kml').onclick=exportKML;$('import-kml').onclick=()=>$('kml-file').click();
$('kml-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('KML 超過 10 MB');const xml=new DOMParser().parseFromString(await file.text(),'application/xml');if(xml.querySelector('parsererror'))throw Error('XML 格式不正確');const tags=(root,name)=>[...root.getElementsByTagNameNS('*',name)],objects=[];for(const mark of tags(xml,'Placemark')){const name=tags(mark,'name')[0]?.textContent||'匯入標繪',description=tags(mark,'description')[0]?.textContent||'';const geometries=[...mark.getElementsByTagName('*')].filter(n=>['Point','LineString','Polygon'].includes(n.localName));for(const g of geometries){if(g.localName==='Polygon'&&tags(g,'innerBoundaryIs').length)throw Error('不支援含孔洞的多邊形；請先轉為單環');const raw=tags(g,'coordinates')[0]?.textContent?.trim();if(!raw)continue;let points=raw.split(/\s+/).map(s=>{const p=s.split(',').map(Number);return[p[1],p[0],p[2]||0]});const type=g.localName==='Point'?'point':g.localName==='LineString'?'line':'polygon';if(type==='polygon'&&points.length>1&&points[0][0]===points.at(-1)[0]&&points[0][1]===points.at(-1)[1])points.pop();const rawColor=tags(mark,'color')[0]?.textContent?.trim();let color=state.settings.color;if(/^[\da-f]{8}$/i.test(rawColor))color='#'+rawColor.slice(6,8)+rawColor.slice(4,6)+rawColor.slice(2,4);objects.push({id:uid(),name,description,type,points,color})}}if(!objects.length)throw Error('沒有 Point、LineString 或 Polygon');const layer={id:uid(),name:file.name.replace(/\.kml$/i,''),visible:true,objects};validateProject({version:2,layers:[layer],activeLayerId:layer.id});snapshot();state.layers.push(layer);state.activeLayerId=layer.id;save('已匯入 '+objects.length+' 個幾何物件，並建立獨立圖層。其他 KML 中繼資料未保留。');renderObjects();renderLayers();openPanel('layers-panel');map.fitBounds(L.latLngBounds(objects.flatMap(o=>o.points)),{padding:[40,40],maxZoom:10})}catch(e){toast('匯入失敗：'+e.message)}e.target.value=''};
function refreshUI(){sanitizePreferences();renderPalette();$('unit').value=state.settings.unit;$('coordinate-format').value=state.settings.format;$('drawing-color').value=state.settings.color;$('basemap').value=state.settings.basemap;$('grid').checked=state.settings.grid;$('show-routes').checked=state.settings.routes;$('show-fixes').checked=state.settings.fixes;setBasemap();renderLayers();renderObjects();renderRouteList();renderRoutes();renderReferences();waypointPicker.renderList();waypointPicker.renderMap();renderGrid();updateCursor();updateInstrumentControls();drawProtractor();renderInstruments();updateScale();renderAxes()}
map.on('move zoom resize',()=>{updateScale();renderAxes();if(!gestures.size)renderInstruments()});map.on('moveend',renderGrid);window.addEventListener('resize',()=>requestAnimationFrame(()=>{map.invalidateSize({pan:false});renderInstruments()}));
function network(){$('network').textContent=navigator.onLine?'● 連線':'● 離線'}window.addEventListener('online',network);window.addEventListener('offline',network);network();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true}};
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).catch(()=>toast('離線快取無法啟用，請使用 HTTPS 或 localhost'));
refreshUI();try{if(localStorage.getItem('map-sidebar-collapsed')==='true')collapseWorkspace(true)}catch{}
Promise.all([fetch('world.json?v=8').then(r=>{if(!r.ok)throw Error('底圖資料');return r.json()}),fetch('routes.json?v=8').then(r=>{if(!r.ok)throw Error('航路資料');return r.json()}),fetch('references.json?v=8').then(r=>{if(!r.ok)throw Error('參考圖層');return r.json()}),fetch('navaids.json?v=8').then(r=>{if(!r.ok)throw Error('航點資料');return r.json()})]).then(([world,data,refs,navaids])=>{L.geoJSON(world,{style:{color:'#567687',weight:1,fillColor:'#1b3745',fillOpacity:.9},onEachFeature:(feature,layer)=>layer.bindTooltip(feature.properties.NAME||feature.properties.ADMIN||'')}).addTo(land);routes=data.routes;references=refs.layers;waypointPicker.setSources(routes,navaids);$('source').href=data.source;refreshUI();save();$('notice').textContent=initialWarning||`已載入 ${routes.length} 條航路、8 座 VOR/DME、ADIZ、海峽中線及官方領海基線。`}).catch(e=>toast('部分圖層載入失敗：'+e.message+'；可繼續本機標繪'));





